local root=assert(os.getenv('QCOM_VP_PROBE_ROOT'))..'/'
platform={moduletype='Container',qemu_inst_mgr={moduletype='QemuInstanceManager'},
    apss_instance={moduletype='QemuInstance',args={'&qemu_inst_mgr','AARCH64'},accel='tcg',
        sync_policy='multithread-quantum',qemu_args='-d in_asm -D '..root..'producer.log'},
    apss_router={moduletype='router'},
    apss_access={moduletype='AccessMonitor',initiator_socket={bind='&apss_router.target_socket'}},
    apss={moduletype='cpu_arm_cortexA53',args={'&apss_instance'},rvbar=0x300000,
        has_el3=true,has_el2=true,mem={bind='&apss_access.target_socket'}},
    rom={moduletype='gs_memory',read_only=true,
        target_socket={address=0x300000,size=0x1000,bind='&apss_router.initiator_socket'},
        load={{bin_file=root..'producer.bin',offset=0}}},
    control={moduletype='qcom,aop-control-v1',
        target_socket={address=0x100000,size=0x418,bind='&apss_router.initiator_socket'}},
    other_control={moduletype='qcom,aop-control-v1',
        target_socket={address=0x110000,size=0x418,bind='&apss_router.initiator_socket'}},
    pair={moduletype='qcom,request-ack-v1',
        target_socket={address=0x120000,size=8,bind='&apss_router.initiator_socket'}},
    other_pair={moduletype='qcom,request-ack-v1',
        target_socket={address=0x120100,size=8,bind='&apss_router.initiator_socket'}},
    crystal={moduletype='qcom,virtual-always-on-clock-v1'},
    upstream={moduletype='qcom,clock-branch-v1',source_path='crystal',
        target_socket={address=0x130000,size=4,bind='&apss_router.initiator_socket'}},
    halt={moduletype='qcom,halt-channel-v1',source_path='upstream',
        target_socket={address=0x140000,size=16,bind='&apss_router.initiator_socket'}},
    other_halt={moduletype='qcom,halt-channel-v1',source_path='upstream',initial_request=0,
        target_socket={address=0x140100,size=16,bind='&apss_router.initiator_socket'}},
    branch={moduletype='qcom,clock-branch-v1',source_path='halt',
        target_socket={address=0x150000,size=4,bind='&apss_router.initiator_socket'}}}
